import{_ as o,o as a,c as r,a2 as t}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Desktop 桌面版安装","description":"","frontmatter":{},"headers":[],"relativePath":"zh/self-hosted/desktop.md","filePath":"zh/self-hosted/desktop.md","lastUpdated":1785920317000}'),l={name:"zh/self-hosted/desktop.md"};function s(d,e,p,i,c,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="desktop-桌面版安装" tabindex="-1">Desktop 桌面版安装 <a class="header-anchor" href="#desktop-桌面版安装" aria-label="Permalink to &quot;Desktop 桌面版安装&quot;">​</a></h1><p>Memoh Desktop 是面向个人和本地使用的原生客户端。它和 Server Deploy 是两条分发线：桌面版默认管理自己的本地后端，而不是连接一个托管的 Web/server 部署。</p><h2 id="什么时候用-desktop" tabindex="-1">什么时候用 Desktop <a class="header-anchor" href="#什么时候用-desktop" aria-label="Permalink to &quot;什么时候用 Desktop&quot;">​</a></h2><p>适合这些场景：</p><ul><li>想要一个打开就能用的本地 App</li><li>单用户或个人工作流</li><li>本地记忆和本地存储</li><li>想用 bundled <code>memoh</code> CLI 连接同一个本地服务</li><li>在自己的电脑上使用 local 或 Docker-backed workspace</li></ul><p>如果你需要多人共享、生产可用性、远程访问，或机器人要在桌面离线时继续服务外部渠道，请用 <a href="/zh/self-hosted/docker.html">Server Deploy</a>。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>从 <a href="https://memoh.ai/desktop" target="_blank" rel="noreferrer">Memoh Desktop 下载页</a> 下载对应平台安装包。</li><li>打开 Memoh。</li><li>等 App 启动本地服务并初始化存储。</li><li>可选：在 App 菜单里安装 bundled <code>memoh</code> CLI。</li></ol><h2 id="desktop-会管理什么" tabindex="-1">Desktop 会管理什么 <a class="header-anchor" href="#desktop-会管理什么" aria-label="Permalink to &quot;Desktop 会管理什么&quot;">​</a></h2><p>桌面版负责本地运行时生命周期：</p><ul><li><code>127.0.0.1:18731</code> 上的本地 <code>memoh-server</code></li><li>系统应用数据目录下的 SQLite 本地数据</li><li>用于记忆向量检索的 embedded Qdrant</li><li>bundled CLI、server binary、provider templates、workspace bridge runtime</li><li>系统托盘唤起与退出行为</li></ul><p>从托盘退出会走桌面端的关闭路径，同时停止它管理的本地 server 和 embedded Qdrant。</p><h2 id="连接远程-server" tabindex="-1">连接远程 server <a class="header-anchor" href="#连接远程-server" aria-label="Permalink to &quot;连接远程 server&quot;">​</a></h2><p>Desktop 也可以不用自己的本地后端，直接作为 <a href="/zh/self-hosted/docker.html">Server Deploy</a> 的客户端。在连接页填 server 地址即可：</p><ul><li>裸域名（如 <code>memoh.example.com</code>）默认按 <code>https://</code> 处理（只有 localhost 类地址才默认 <code>http://</code>）。</li><li>缺 <code>/api</code> 路径后缀会自动补——只填域名就够。</li><li>连接前会探测 server 的 <code>/ping</code>（5 秒超时），通过后进登录页。</li></ul><p>换连别的 server 会清掉本地登录态，需要在新 server 上重新登录。</p><h2 id="把这台电脑共享给机器人" tabindex="-1">把这台电脑共享给机器人 <a class="header-anchor" href="#把这台电脑共享给机器人" aria-label="Permalink to &quot;把这台电脑共享给机器人&quot;">​</a></h2><p>Desktop 可以把它所在的这台机器注册成 server 侧机器人可用的<strong>电脑</strong>，不用另跑 runtime 进程：打开<strong>这台电脑</strong>开关、起个名字，Desktop 在后台维持连接。权限模型和按机器人的配置见 <a href="/zh/guides/computers.html">电脑（远程 Runtime）</a>。</p><h2 id="workspace-行为" tabindex="-1">Workspace 行为 <a class="header-anchor" href="#workspace-行为" aria-label="Permalink to &quot;Workspace 行为&quot;">​</a></h2><p>Desktop 可按配置使用 trusted local workspace 或 container-backed workspace。Trusted local workspace 以本地用户权限运行，不提供容器隔离；container-backed workspace 仍保留正常的 bot workspace 模型，可用于文件编辑、命令执行、MCP 托管，以及可选的桌面显示/浏览器会话。</p><p>运行时差异见 <a href="/zh/self-hosted/workspace-backends.html">Workspace backend</a>。</p>',21)])])}const m=o(l,[["render",s]]);export{k as __pageData,m as default};
